import asyncio


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently from synchronous code, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and its result is None.
    Works with repeated calls in the same process."""
    async def _main():
        tasks = [asyncio.create_task(c) for c in coros]

        done, pending = await asyncio.wait(tasks, timeout=seconds)

        # Cancel all pending tasks (not finished within timeout)
        for t in pending:
            t.cancel()

        # Await cancellation completion for pending tasks
        await asyncio.gather(*pending, return_exceptions=True)

        results = []
        for t in tasks:
            if t in done:
                try:
                    results.append(t.result())
                except Exception:
                    # If a task raised, propagate the exception
                    raise
            else:
                # Task was cancelled due to timeout
                results.append(None)
        return results

    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        # No running loop, safe to use asyncio.run
        return asyncio.run(_main())
    else:
        # Running loop exists, run _main in a new thread to avoid nested event loop error
        import threading

        result = []
        exc = []

        def runner():
            try:
                result.append(asyncio.run(_main()))
            except Exception as e:
                exc.append(e)

        t = threading.Thread(target=runner)
        t.start()
        t.join()
        if exc:
            raise exc[0]
        return result[0]

from web_utils import parse_content_type, content_charset, image_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """Given Content-Type header and first bytes of body, return a dict with keys:
    - "mime": lower-cased media type without parameters
    - "charset": lower-cased charset parameter or None if not present
    - "image": one of "png", "jpeg", "gif" or None detected from data signature bytes
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()
    else:
        charset = None
    try:
        img_type = image_type(data)
    except PermissionError:
        # image_type detection requires third-party libs; fallback to None
        img_type = None
    return {"mime": mime, "charset": charset, "image": img_type}

