                pass
        # Collect results in input order
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from completed tasks
                    raise
            else:
                results.append(None)
        return results

    return run_sync(_run_all_with_deadline())

